#!/usr/bin/env node
// @ts-check
/**
 * Renders `results/dashboard.json`, the data set behind the dashboard: the history of both indices,
 * the evals of both suites with their next steps, and one cell per component × eval with a concrete
 * hint derived from what the metric recorded for that component. Regenerated by every full
 * `npm run evals` and by `npm run evals:dashboard`; a test asserts the committed file is fresh.
 *
 *   node evals/ai-friendliness/tools/dashboard-data.mjs
 *
 * The dashboard reads this document from the artifact database; the file is the source to publish.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { insideDir } from '../lib/paths.mjs';
import { FREE_PROPS } from '../metrics/E02-prop-surface.mjs';
import { FREE_DEPTH, FREE_ELEMENTS } from '../metrics/E07-markup-depth.mjs';

export const DASHBOARD_FILE = 'results/dashboard.json';

/** Evals whose per-component rows are components (E04 reports files, so it has no heatmap column). */
export const HEATMAP_EVALS = ['E01', 'E02', 'E03', 'E05', 'E06', 'E07', 'E08', 'E09', 'E10'];
/** Enterprise evals with per-component rows (R01 is per requirement). */
export const ENTERPRISE_HEATMAP_EVALS = ['R02', 'R03', 'R04', 'R05', 'R06'];
const ALL_HEATMAP = new Set([...HEATMAP_EVALS, ...ENTERPRISE_HEATMAP_EVALS]);

/** Evals that measure TypeScript patterns only; CSS-only components are out of their scope. */
const PATTERN_ONLY = new Set(['E01', 'E02', 'E03', 'E05', 'E06', 'E10', 'R03']);

/** What a per-component cell of each eval means, and why some cells have no value. */
const SCOPE = {
	E01: 'Per pattern: tokens an agent must read to use it (its manifest card when ≥ 80 % complete, else the API + config + enum + interface files). CSS-only components have no TypeScript contract.',
	E02: 'Per pattern: how many config props it has and how many are precisely typed. CSS-only components have no props.',
	E03: 'Per pattern: how complete its entry in docs-ai/osui.components.json is across six facets. CSS-only components are documented in llms-patterns.txt instead.',
	E04: 'Measured per file over the whole program (implicit any, explicit any, suppressions, return types), so it has no per-component cell.',
	E05: 'Per pattern: API functions and config props with documentation (cell = documented share). CSS-only components have no API.',
	E06: 'Per pattern: canonical API members present, functions returning the response envelope, camelCase parameters. CSS-only components have no API.',
	E07: 'Per component: depth and distinct parts of the deepest HTML template in its Storybook story. Components without a story cannot be measured.',
	E08: 'Per component SCSS: themeable declarations that are hardcoded, routed through --osui-* knobs, or read a token. Files with nothing themeable cannot be scored.',
	E09: 'Per component SCSS: mean combinators per selector and the p90 class specificity. Files with no rules cannot be scored.',
	E10: 'Per pattern: inheritance depth, contract files, typed configs and events, module format. CSS-only components have no classes.',
	R01: 'Per requirement of the enterprise UI document, not per component: offered, partial or missing, with delegated rows for other OutSystems products.',
	R02: 'Per component: ARIA set and, where the role needs it, feedback announced and focus managed (patterns); .has-accessible-features and .os-high-contrast styles (every component with CSS).',
	R03: 'Per interactive pattern: the keys its role needs (Enter/Space; Escape and tab order for overlays; Arrow keys and tab order for composite widgets). CSS-only components have no script.',
	R04: 'Per component CSS: declared foundation families read via tokens or knobs, dark-ready colours, RTL rules where direction matters, a reduced-motion guard where it animates.',
	R05: 'Per component CSS: breakpoint rules where it lays out, a size or density axis where the document expects one, RTL rules where direction matters.',
	R06: 'Per component: hover, focus-visible, press/open and disabled states where interactive; loading, invalid and guarded motion where they apply.',
};

const pct = (/** @type {number} */ a, /** @type {number} */ b) => (b ? Math.round((100 * a) / b) : 100);
const r1 = (/** @type {number} */ n) => Math.round(n * 10) / 10;
const list = (/** @type {string[]} */ xs, max = 4) =>
	xs.length > max ? `${xs.slice(0, max).join(', ')} +${xs.length - max} more` : xs.join(', ');

/** @typedef {{ s: number|null, w: 'ok'|'na'|'unmeasured', h: string }} Cell */

/**
 * @param {number|null} s
 * @param {string} h
 * @returns {Cell}
 */
const ok = (s, h) => ({ s, w: 'ok', h });

/** @param {string[]} todo @param {string} [fallback] */
const toDoHint = (todo, fallback = '') => (todo.length ? ` To do: ${todo.join('; ')}.` : fallback);

/**
 * @param {string} id
 * @param {{ kind?: string, reason?: string }} ctx
 * @returns {Cell}
 */
function missingCell(id, ctx) {
	if (PATTERN_ONLY.has(id) && ctx.kind === 'css') {
		return {
			s: null,
			w: 'na',
			h: 'Not applicable: this eval measures the TypeScript contract and this is a CSS-only component.',
		};
	}
	const reason = ctx.reason ?? 'no measurement in this run';
	const fix = {
		E07: 'Add a Storybook story with an HTML template so the markup contract can be measured.',
		E08: 'Nothing to change: the compiled CSS has no colour, spacing, radius or typography declarations to theme.',
		E09: 'Nothing to change: the partial compiles to no rules.',
	}[id];
	const fixHint = fix ? ` ${fix}` : '';
	return { s: null, w: 'unmeasured', h: `Not measured (${reason}).${fixHint}` };
}

/** @param {any} row */
function e01NextStep(row) {
	if (row.source === 'manifest card') {
		return row.score < 100 ? ' Trim the card: fewer or shorter prop descriptions.' : '';
	}
	return row.cardTokens === null
		? ' The manifest card is below 80 % complete, so agents fall back to the source: complete its facets.'
		: '';
}

/** Per-eval heatmap cell for a component the metric measured. @type {Record<string, (row: any) => Cell>} */
const CELL_BUILDERS = {
	E01: (row) => {
		const via =
			row.source === 'manifest card'
				? `via its manifest card (${row.tokens} tokens; source contract ${row.srcTokens} across ${row.files} files)`
				: `from the source contract (${row.tokens} tokens across ${row.files} files)`;
		return ok(row.score, `Read ${via}.${e01NextStep(row)}`);
	},
	E02: (row) => {
		const parts = [`${row.precise} of ${row.n} props precise`];
		if (row.n > FREE_PROPS) parts.push(`${row.n - FREE_PROPS} props over the free allowance of ${FREE_PROPS}`);
		const todo = [];
		if (row.stringlyTypedEnums?.length)
			todo.push(
				`type as enums: ${list(row.stringlyTypedEnums.map((/** @type {string} */ s) => s.split(' (')[0]))}`
			);
		if (row.untyped?.length) todo.push(`give a type to: ${list(row.untyped)}`);
		return ok(row.score, `${parts.join('; ')}.${toDoHint(todo)}`);
	},
	E03: (row) => {
		if (!row.present) return ok(row.score, 'Missing from the manifest: run npm run docs:ai.');
		const weak = Object.entries(row.facets ?? {})
			.filter(([, v]) => Number(v) < 100)
			.map(([k, v]) => `${k} ${v}`);
		return ok(
			row.score,
			weak.length
				? `Facets below 100: ${weak.join(', ')}. Add the missing defaults, descriptions or markup skeleton to the source the generator reads.`
				: 'All six manifest facets complete.'
		);
	},
	E05: (row) => {
		const total = row.apiTotal + row.propsTotal;
		const done = row.apiDocumented + row.propsDocumented;
		const todo = [
			...(row.undocumentedApi ?? []).map((/** @type {string} */ f) => `${f}()`),
			...(row.undocumentedProps ?? []),
		];
		const documentHint = todo.length ? ` Document: ${list(todo)}.` : '';
		return ok(
			pct(done, total),
			`${row.apiDocumented}/${row.apiTotal} API functions and ${row.propsDocumented}/${row.propsTotal} props documented.${documentHint}`
		);
	},
	E06: (row) => {
		const todo = [];
		if (row.missing?.length) todo.push(`add canonical members: ${list(row.missing)}`);
		if (row.unwrapped?.length)
			todo.push(`return the response envelope from: ${list(row.unwrapped)} (behaviour change, see B-3)`);
		if (row.nonCamelParams?.length) todo.push(`camelCase parameters: ${list(row.nonCamelParams)}`);
		if (row.inlineCodes?.length) todo.push(`replace inline error codes: ${list(row.inlineCodes)}`);
		return ok(row.score, `${row.functions} API functions.${toDoHint(todo, ' Matches the canonical shape.')}`);
	},
	E07: (row) => {
		const over = [];
		if (row.depth > FREE_DEPTH) over.push(`${row.depth - FREE_DEPTH} levels over the free depth of ${FREE_DEPTH}`);
		if (row.elements > FREE_ELEMENTS)
			over.push(`${row.elements - FREE_ELEMENTS} parts over the free ${FREE_ELEMENTS}`);
		const overHint = over.length
			? ` ${over.join('; ')}. Flattening needs a DOM-contract change (B-5).`
			: ' Within the allowance.';
		return ok(
			row.score,
			`Story markup: depth ${row.depth}, ${row.elements} distinct parts, ${row.classes} classes.${overHint}`
		);
	},
	E08: (row) => {
		const todo = [];
		if (row.literal) todo.push(`replace ${row.literal} hardcoded values with tokens`);
		if (row.total && row.routed / row.total < 0.6)
			todo.push(`route more reads through --osui-* knobs (${row.knobs} knobs today; B-7)`);
		if (row.important) todo.push(`remove ${row.important} !important (B-8)`);
		return ok(
			row.score,
			`${row.routed} of ${row.total} themeable declarations read via --osui-* knobs, ${row.literal} hardcoded, ${row.important} !important.${toDoHint(todo)}`
		);
	},
	E09: (row) => {
		const todo = [];
		if (row.avgDepth > 1) todo.push('flatten combinator chains into state classes on the styled element (B-6)');
		if (row.p90b > 2) todo.push(`lower class specificity (p90 ${row.p90b}, max depth ${row.maxDepth})`);
		return ok(
			row.score,
			`${row.selectors} selectors, mean ${r1(row.avgDepth)} combinators, p90 class specificity ${row.p90b}.${toDoHint(todo, ' Flat cascade.')}`
		);
	},
	E10: (row) => {
		const todo = [];
		if (row.depth > 1) todo.push(`inheritance depth ${row.depth} (${row.chain})`);
		if (row.files > 4) todo.push(`${row.files} contract files (free allowance 4)`);
		if (row.configShape === 0) todo.push('Create accepts only a JSON string');
		if (row.eventModel === 0) todo.push('event names typed as string');
		if (row.moduleFormat === 0) todo.push('global namespace instead of an ES module (B-4)');
		return ok(row.score, todo.length ? `Costs: ${todo.join('; ')}.` : 'Flat, typed and modular.');
	},
};

/**
 * One heatmap cell: `s` score (or null), `w` why (`ok` | `na` | `unmeasured`), `h` hint text.
 * @param {string} id eval id
 * @param {any} row the metric's per-component row, or null when it has none for this component
 * @param {{ kind?: string, reason?: string }} [ctx]
 * @returns {Cell}
 */
export function cellFor(id, row, ctx = {}) {
	if (!row) return missingCell(id, ctx);
	const build = CELL_BUILDERS[id];
	if (build) return build(row);
	if (ENTERPRISE_HEATMAP_EVALS.includes(id)) return enterpriseCell(id, row);
	return ok(typeof row.score === 'number' ? row.score : null, '');
}

/**
 * Enterprise cells share one shape: applicable checks with a failed list.
 * @param {string} id
 * @param {any} row
 * @returns {Cell}
 */
function enterpriseCell(id, row) {
	const failed = /** @type {string[]} */ (row.failed ?? []);
	const extras = [];
	if (id === 'R03' && row.delegated) extras.push('keys handled by the provider library, not the wrapper');
	if (id === 'R04' && row.untokened?.length) extras.push(`families read with literals: ${row.untokened.join(', ')}`);
	if (id === 'R05' && row.checks?.density?.knobs?.length)
		extras.push(`density knobs: ${row.checks.density.knobs.join(', ')}`);
	const head = failed.length ? `Missing: ${failed.join('; ')}.` : 'Every applicable check passes.';
	const tail = extras.length ? ` ${extras.join('. ')}.` : '';
	return ok(row.score, `${head}${tail}`);
}

/**
 * Next steps for the enterprise-readiness evals, from their rows and totals.
 * @param {any} m metric result of the latest run
 * @param {any[]} rows
 * @param {any} raw
 * @returns {string[]}
 */
function adviceForEnterprise(m, rows, raw) {
	switch (m.id) {
		case 'R01': {
			const missing = rows.filter((r) => !r.delegated && r.status === 'missing').map((r) => r.name);
			const partial = rows.filter((r) => !r.delegated && r.status === 'partial').map((r) => r.name);
			const flows = (raw.flows ?? [])
				.filter((/** @type {any} */ f) => f.kit !== 'complete')
				.map((/** @type {any} */ f) => `${f.flow} (${[...f.missing, ...f.partial].join(', ')})`);
			return [
				`Missing (${missing.length}): ${list(missing, 12)}.`,
				`Partial (${partial.length}): ${list(partial, 12)}.`,
				flows.length
					? `Flows not kit-complete: ${flows.join('; ')}.`
					: 'Every flow of the document is kit-complete.',
				'Each missing item is new work (roadmap), not a refactor; delegated rows (Table, Data Grid, Charts, Maps) are reported but not scored.',
			];
		}
		case 'R02': {
			const noAria = raw.patternsWithoutAria ?? [];
			return [
				m.summary,
				noAria.length
					? `Patterns setting no ARIA from TypeScript: ${list(noAria, 8)} (provider-rendered pickers rely on their library).`
					: 'Every pattern sets ARIA.',
				'Adding .has-accessible-features and .os-high-contrast rules per component is additive; a dynamic axe pass over Storybook is the next step for real violations.',
			];
		}
		case 'R03':
			return [
				m.summary,
				`Missing keys: ${list(raw.missing ?? [], 8)}.`,
				'Key handlers are additive; overlays need Escape and a managed tab order, composite widgets need Arrow keys.',
			];
		case 'R04':
			return [
				m.summary,
				'Dark mode follows the token set, so the remaining work is literal colour reads and the reduced-motion guard on animating components; both additive.',
			];
		case 'R05':
			return [
				m.summary,
				`No density axis yet: ${list(raw.densityMissing ?? [], 10)}. Knobs with defaults equal to today are additive; variant classes that change defaults are structural.`,
			];
		case 'R06':
			return [
				m.summary,
				'State styles and prefers-reduced-motion guards are additive; a skeleton-loading component is R01 roadmap work.',
			];
		default:
			return [m.summary];
	}
}

/**
 * Eval-level next steps, derived from the latest per-component rows and totals.
 * @param {any} m metric result of the latest run
 * @returns {string[]}
 */
export function adviceFor(m) {
	const rows = /** @type {any[]} */ (Object.values(m.perComponent ?? {}));
	const raw = m.raw ?? {};
	if (m.id.startsWith('R')) return adviceForEnterprise(m, rows, raw);
	switch (m.id) {
		case 'E01': {
			const src = rows.filter((r) => r.source !== 'manifest card');
			return [
				`Mean ${raw.meanTokens} tokens per pattern via cards, against ${raw.meanSourceTokens} from source; benchmark median ${raw.benchmark?.median ?? 912}.`,
				src.length
					? `${src.length} patterns still read from source (card below 80 % complete): ${list(src.map((r) => r.name))}.`
					: 'Every pattern is served by its manifest card; keep cards complete so this holds.',
				`The compiled .d.ts is ${raw.publicTypingsTokens ? Math.round(raw.publicTypingsTokens / 1000) : '~51'}k tokens: agents must load a card, never the whole typing file.`,
			];
		}
		case 'E02': {
			const stringly = rows.flatMap((r) =>
				(r.stringlyTypedEnums ?? []).map((/** @type {string} */ s) => `${r.name}.${s.split(' (')[0]}`)
			);
			const big = rows.filter((r) => r.n > FREE_PROPS).map((r) => `${r.name} (${r.n})`);
			return [
				stringly.length
					? `${stringly.length} stringly-typed enums remain: ${list(stringly, 7)}. Turning them into validated enum types changes runtime fallback behaviour (B-9).`
					: 'No stringly-typed enums remain.',
				big.length
					? `Patterns over the free allowance of ${FREE_PROPS} props: ${list(big, 6)}; splitting or grouping props is a public-contract change.`
					: 'No pattern exceeds the prop allowance.',
			];
		}
		case 'E03': {
			const facetMeans = Object.entries(raw.facetMeans ?? {})
				.map(([k, v]) => `${k} ${v}`)
				.join(', ');
			return [
				`${raw.patterns}/${raw.entries ?? raw.patterns} patterns in the manifest; facet means ${facetMeans}.`,
				'Keep it at 100 by running npm run docs:ai in every PR that touches a pattern; the CI freshness check fails a stale commit.',
			];
		}
		case 'E04':
			return [
				`${raw.implicit} implicit-any, ${raw.explicit} explicit any, ${raw.suppressions} suppressions, ${raw.missingReturnTypes}/${raw.publicFunctions} public functions without a return type over ${raw.kloc} KLOC; noImplicitAny is on.`,
				'Next step of this kind: strictNullChecks, which is a larger behaviour-neutral annotation pass.',
			];
		case 'E05':
			return [
				m.summary,
				'Coverage is complete; the generator reads the same JSDoc, so new functions and props need a comment before docs-ai regenerates.',
			];
		case 'E06': {
			const unwrapped = rows.flatMap((r) =>
				(r.unwrapped ?? []).map((/** @type {string} */ f) => `${r.name}.${f}`)
			);
			return [
				unwrapped.length
					? `${unwrapped.length} functions return void instead of the response envelope: ${list(unwrapped, 6)}. Wrapping them changes error propagation (B-3).`
					: 'Every eligible function returns the response envelope.',
				`${raw.missingTotal} missing canonical members, ${raw.nonCamelTotal} non-camelCase parameters.`,
			];
		}
		case 'E07': {
			const deep = rows
				.filter((r) => r.score < 60)
				.sort((a, b) => a.score - b.score)
				.map((r) => `${r.name} (depth ${r.depth}, ${r.elements} parts)`);
			return [
				`${m.unmeasured?.length ?? 0} components have no story: add one HTML template each to measure them.`,
				deep.length
					? `Deepest contracts: ${list(deep, 6)}. Flattening them is a DOM-contract change (B-5).`
					: 'No component below 60.',
			];
		}
		case 'E08': {
			const worst = rows
				.filter((r) => r.total >= 10)
				.sort((a, b) => a.routed / a.total - b.routed / b.total)
				.slice(0, 6)
				.map((r) => `${r.name} (${r.routed}/${r.total})`);
			return [
				`${raw.routed} of ${raw.total} themeable declarations (${Math.round((100 * raw.routed) / raw.total)} %) read through --osui-* knobs; ${raw.literal} hardcoded; ${raw.important} !important.`,
				`Lowest knob routing: ${list(worst, 6)}. Routing is additive when the knob default equals the current value, except for portaled elements (B-7).`,
			];
		}
		case 'E09': {
			rows.sort((a, b) => a.score - b.score);
			const worst = rows.slice(0, 6).map((r) => `${r.name} (p90 ${r.p90b}, max ${r.maxDepth})`);
			return [
				m.summary,
				`Highest specificity: ${list(worst, 6)}. Flattening into state classes changes cascade order for existing overrides (B-6).`,
			];
		}
		case 'E10':
			return [
				`Mean inheritance depth ${raw.meanDepth} (max ${raw.maxDepth}), mean ${raw.meanFiles} contract files; ${raw.jsonStringConfigs} JSON-string-only Create, ${raw.stringEventNames} string event names, ${raw.globalNamespaceApis} global-namespace APIs.`,
				'Configs and events are typed additively (S-9). The remaining cost is the AMD global namespace and provider inheritance chains, which need the ES-module facade (B-4).',
			];
		default:
			return [m.summary];
	}
}

/**
 * @param {Map<string, string>} map
 * @param {string} key
 * @param {string} value
 */
function setIfAbsent(map, key, value) {
	if (!map.has(key)) map.set(key, value);
}

/**
 * Component universe and kind: E07 knows every component, E02 names the patterns.
 * @param {any[]} results metric results of the latest run
 * @returns {Map<string, string>}
 */
function componentKinds(results) {
	/** @type {Map<string, string>} */
	const kinds = new Map();
	const e07 = results.find((m) => m.id === 'E07');
	for (const row of Object.values(e07?.perComponent ?? {}))
		kinds.set(/** @type {any} */ (row).name, /** @type {any} */ (row).kind);
	for (const u of e07?.unmeasured ?? []) setIfAbsent(kinds, u.name, 'css');
	for (const m of results.filter((r) => ALL_HEATMAP.has(r.id))) {
		for (const row of Object.values(m.perComponent ?? {})) {
			const r = /** @type {any} */ (row);
			setIfAbsent(kinds, r.name, r.kind ?? (PATTERN_ONLY.has(m.id) ? 'pattern' : 'css'));
		}
	}
	const e02 = results.find((m) => m.id === 'E02');
	for (const r of Object.values(e02?.perComponent ?? {})) kinds.set(/** @type {any} */ (r).name, 'pattern');
	return kinds;
}

/**
 * @param {any[]} results metric results of the latest run
 * @param {string} name component name
 * @param {string} kind component kind
 * @returns {Record<string, Cell>}
 */
function componentCells(results, name, kind) {
	/** @type {Record<string, Cell>} */
	const cells = {};
	for (const m of results) {
		if (!ALL_HEATMAP.has(m.id)) continue;
		const row = Object.values(m.perComponent ?? {}).find((/** @type {any} */ r) => r.name === name) ?? null;
		const na = (m.notApplicable ?? []).find((/** @type {any} */ u) => u.name === name);
		if (na) {
			cells[m.id] = {
				s: null,
				w: 'na',
				h: `Not applicable: ${na.reason}. Style it through its --osui-* knobs; the markup is not yours to emit.`,
			};
			continue;
		}
		const un = (m.unmeasured ?? []).find(
			(/** @type {any} */ u) => u.name === name || u.name.startsWith(`${name} (`)
		);
		cells[m.id] = cellFor(m.id, row, { kind, reason: un?.reason });
	}
	return cells;
}

/**
 * The enterprise suite of the data set: present from the first history entry that carries it.
 * @param {{ label: string, sha: string, date: string, enterprise?: { scores: Record<string, number>, index: number } }[]} history sorted by date
 * @param {any} latest the latest run file
 * @param {(m: any, baseScores: Record<string, number>) => any} evalOf
 */
function enterpriseBlock(history, latest, evalOf) {
	const first = history.find((h) => h.enterprise);
	if (!first?.enterprise || !latest.enterprise) return null;
	const results = /** @type {any[]} */ (latest.enterprise.results ?? []);
	const r01 = results.find((m) => m.id === 'R01');
	return {
		evals: results.map((m) => evalOf(m, first.enterprise?.scores ?? {})),
		heatmapEvals: ENTERPRISE_HEATMAP_EVALS,
		baseline: { label: first.label, sha: first.sha, date: first.date, index: first.enterprise.index },
		latest: { index: latest.enterprise.index },
		requirements: /** @type {any[]} */ (r01?.perComponent ?? []).map((r) => ({
			id: r.id,
			name: r.name,
			group: r.group,
			owner: r.owner,
			status: r.status,
			reason: r.reason,
		})),
		flows: r01?.raw?.flows ?? [],
	};
}

/**
 * @param {string} suiteDir
 * @param {Date} [now]
 */
export function buildDashboardData(suiteDir, now = new Date()) {
	const read = (/** @type {string} */ ...p) =>
		JSON.parse(fs.readFileSync(insideDir(suiteDir, 'results', ...p), 'utf8'));
	/** @type {{ label: string, date: string, sha: string, scores: Record<string, number>, index: number }[]} */
	const history = [...read('history.json')].sort((a, b) => a.date.localeCompare(b.date));
	const first = history[0];
	const last = history[history.length - 1];
	const latest = read(`${last.label}.json`);
	const baseline = read(`${first.label}.json`);

	/** @param {any} m @param {Record<string, number>} baseScores */
	const evalOf = (m, baseScores) => ({
		id: m.id,
		name: m.name,
		criterion: m.criterion,
		formula: m.formula,
		movable: m.movable,
		cls: m.cls ?? (m.movable ? 'movable' : 'structural'),
		score: m.score,
		base: baseScores[m.id] ?? null,
		summary: m.summary,
		scope: SCOPE[/** @type {keyof typeof SCOPE} */ (m.id)],
		advice: adviceFor(m),
		unmeasured: {
			n: (m.unmeasured ?? []).length,
			items: (m.unmeasured ?? []).map((/** @type {any} */ u) => ({
				n: u.name.replace(/ \(.*\)$/, ''),
				r: u.reason,
			})),
		},
	});
	const evals = latest.results.map((/** @type {any} */ m) => evalOf(m, baseline.scores));

	const enterpriseResults = latest.enterprise?.results ?? [];
	const enterprise = enterpriseBlock(history, latest, evalOf);

	const allResults = [...latest.results, ...enterpriseResults];
	const kinds = componentKinds(allResults);
	const components = [...kinds.keys()]
		.sort((a, b) => a.localeCompare(b))
		.map((name) => {
			const kind = kinds.get(name) ?? 'css';
			return { n: name, k: kind, cells: componentCells(allResults, name, kind) };
		});

	return {
		v: 2,
		generated: now.toISOString(),
		latest: { label: last.label, sha: last.sha, date: last.date, index: last.index },
		baseline: { label: first.label, sha: first.sha, date: first.date, index: first.index },
		history,
		evals,
		heatmapEvals: HEATMAP_EVALS,
		components,
		enterprise,
	};
}

/**
 * @param {string} suiteDir
 */
export function writeDashboardData(suiteDir) {
	const file = insideDir(suiteDir, DASHBOARD_FILE);
	fs.writeFileSync(file, `${JSON.stringify(buildDashboardData(suiteDir))}\n`);
	return file;
}

function main() {
	const suiteDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
	const file = writeDashboardData(suiteDir);
	process.stdout.write(`wrote ${path.relative(process.cwd(), file)} (${fs.statSync(file).size} bytes)\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
